/**
 * Server-side Application / Use Case Layer (INFRA-02 Step 04).
 *
 * Coordinates domain repositories, transaction boundaries, and tenant context.
 */
class BackendUseCases(
    private val transactionManager: TransactionManager,
    private val repositoryFactory: PostgresRepositoryFactory
) {

    private val idempotencyStore = ConcurrentHashMap<String, ApiSuccessResponse<*>>()

    // =========================================================================
    // 1. CUSTOMER USE CASES
    // =========================================================================

    suspend fun getCustomerProfile(principal: AuthenticatedPrincipal): CustomerProfileDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.CUSTOMER, UserRole.STAFF, UserRole.ADMIN)
        BackendAuthorizationPolicy.enforceCustomerOwnership(principal, principal.userId)

        val tenantContext = TenantContext(principal.projectId)
        val customerRepo = repositoryFactory.createCustomerRepository(principal.projectId)

        return transactionManager.inReadOnly(tenantContext) {
            when (val res = customerRepo.findCustomerById(principal.userId)) {
                is DomainResult.Success -> {
                    val c = res.data
                    CustomerProfileDto(
                        customerId = c.customerId,
                        customerCode = c.customerCode,
                        name = c.displayName,
                        companyName = c.contactPersonName,
                        email = c.email,
                        phone = c.primaryPhone,
                        creditLimit = c.creditProfile.creditLimit.amount,
                        currentBalance = BigDecimal.ZERO,
                        status = c.status.name
                    )
                }
                else -> throw NotFoundException("Customer profile not found for '${principal.userId}'.")
            }
        }
    }

    suspend fun getCustomerOrders(principal: AuthenticatedPrincipal): List<CustomerOrderSummaryDto> {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.CUSTOMER, UserRole.STAFF, UserRole.ADMIN)
        BackendAuthorizationPolicy.enforceCustomerOwnership(principal, principal.userId)

        val tenantContext = TenantContext(principal.projectId)
        val orderRepo = repositoryFactory.createOrderRepository(principal.projectId)

        return transactionManager.inReadOnly(tenantContext) {
            val orders = orderRepo.getOrdersForCustomer(principal.userId).first()
            orders.map { order ->
                CustomerOrderSummaryDto(
                    orderId = order.orderId,
                    orderNumber = order.orderNumber,
                    status = order.status.name,
                    totalAmount = order.totalAmount.amount,
                    createdAt = System.currentTimeMillis()
                )
            }
        }
    }

    suspend fun getCustomerOrderDetail(principal: AuthenticatedPrincipal, orderId: String): CustomerOrderDetailDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.CUSTOMER, UserRole.STAFF, UserRole.ADMIN)

        val tenantContext = TenantContext(principal.projectId)
        val orderRepo = repositoryFactory.createOrderRepository(principal.projectId)

        return transactionManager.inReadOnly(tenantContext) {
            val order = when (val res = orderRepo.findOrderById(orderId)) {
                is DomainResult.Success -> res.data
                else -> throw NotFoundException("Order '$orderId' not found.")
            }

            // Verify ownership: Customer can only access their own order
            BackendAuthorizationPolicy.enforceCustomerOwnership(principal, order.customerId)

            CustomerOrderDetailDto(
                orderId = order.orderId,
                orderNumber = order.orderNumber,
                customerId = order.customerId,
                status = order.status.name,
                items = order.items.map { item ->
                    OrderItemDto(
                        itemId = item.itemId,
                        description = item.description,
                        quantity = item.quantity,
                        unitPrice = item.unitPrice.amount,
                        totalPrice = item.lineSubtotal.amount
                    )
                },
                subtotal = order.subtotal.amount,
                discount = order.discount.amount,
                totalAmount = order.totalAmount.amount,
                notes = order.notes,
                version = 1L,
                createdAt = System.currentTimeMillis()
            )
        }
    }

    suspend fun createCustomerOrder(
        principal: AuthenticatedPrincipal,
        request: CreateOrderRequestDto,
        idempotencyKey: String? = null
    ): CustomerOrderDetailDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.CUSTOMER, UserRole.STAFF, UserRole.ADMIN)
        BackendAuthorizationPolicy.requirePermission(principal, UserPermission.CREATE_ORDER)

        if (request.items.isEmpty()) {
            throw ValidationException("Order must contain at least one item.")
        }

        // Idempotency check: tenant-scoped
        val effectiveKey = idempotencyKey ?: request.idempotencyKey
        if (effectiveKey != null) {
            val scopedKey = "${principal.projectId}:$effectiveKey"
            val cached = idempotencyStore[scopedKey]
            if (cached != null) {
                @Suppress("UNCHECKED_CAST")
                return cached.data as CustomerOrderDetailDto
            }
        }

        val tenantContext = TenantContext(principal.projectId)
        val orderRepo = repositoryFactory.createOrderRepository(principal.projectId)

        val orderId = "ORD-${UUID.randomUUID().toString().take(8).uppercase()}"
        val orderNumber = "SO-${System.currentTimeMillis().toString().takeLast(6)}"
        val nowIso = "2026-08-23T16:35:00Z"

        val domainItems = request.items.mapIndexed { idx, item ->
            OrderItem(
                itemId = "ITEM-${orderId}-$idx",
                description = item.description,
                quantity = item.quantity,
                unitPrice = Money(item.unitPrice)
            )
        }

        val domainOrder = Order(
            orderId = orderId,
            orderNumber = orderNumber,
            customerId = principal.userId,
            quotationId = null,
            approvedQuotationRevisionId = null,
            status = OrderStatusType.CONFIRMED,
            priority = OrderPriority.NORMAL,
            items = domainItems,
            discount = Money.ZERO,
            jobHandoffStatus = JobHandoffStatus.READY_FOR_JOB,
            notes = request.notes,
            confirmedBy = principal.username,
            confirmedAt = nowIso,
            createdAt = nowIso,
            updatedAt = nowIso
        )

        val created = transactionManager.inTransaction(tenantContext) {
            val result = orderRepo.createOrder(domainOrder)
            if (result !is DomainResult.Success) {
                val errMsg = if (result is DomainResult.Error) result.message else "Failed to persist order"
                throw ValidationException("Failed to persist order: $errMsg")
            }
            CustomerOrderDetailDto(
                orderId = domainOrder.orderId,
                orderNumber = domainOrder.orderNumber,
                customerId = domainOrder.customerId,
                status = domainOrder.status.name,
                items = domainOrder.items.map { item ->
                    OrderItemDto(
                        itemId = item.itemId,
                        description = item.description,
                        quantity = item.quantity,
                        unitPrice = item.unitPrice.amount,
                        totalPrice = item.lineSubtotal.amount
                    )
                },
                subtotal = domainOrder.subtotal.amount,
                discount = domainOrder.discount.amount,
                totalAmount = domainOrder.totalAmount.amount,
                notes = domainOrder.notes,
                version = 1L,
                createdAt = System.currentTimeMillis()
            )
        }

        if (effectiveKey != null) {
            val scopedKey = "${principal.projectId}:$effectiveKey"
            idempotencyStore[scopedKey] = ApiSuccessResponse(data = created)
        }

        return created
    }

