    suspend fun createVendor(principal: AuthenticatedPrincipal, request: CreateVendorRequestDto): VendorDetailDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)

        val vendorService = repositoryFactory.createVendorService(principal.projectId)
        val type = request.vendorType?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorType.valueOf(it.uppercase()) }.getOrNull() }
            ?: com.sucharu.sucharupro.domain.model.vendor.VendorType.SERVICE_PROVIDER
        val category = request.vendorCategory?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorCategory.valueOf(it.uppercase()) }.getOrNull() }
            ?: com.sucharu.sucharupro.domain.model.vendor.VendorCategory.OTHER
        val status = request.status?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorStatus.valueOf(it.uppercase()) }.getOrNull() }
            ?: com.sucharu.sucharupro.domain.model.vendor.VendorStatus.ACTIVE

        return when (val res = vendorService.createVendor(
            projectId = principal.projectId,
            vendorName = request.vendorName,
            vendorCode = request.vendorCode,
            legalName = request.legalName,
            vendorType = type,
            vendorCategory = category,
            status = status,
            primaryContactName = request.primaryContactName,
            primaryPhone = request.primaryPhone,
            primaryEmail = request.primaryEmail,
            notes = request.notes,
            createdBy = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDetailDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

