    suspend fun updateVendorStatus(principal: AuthenticatedPrincipal, vendorId: String, request: UpdateVendorStatusRequestDto): VendorDetailDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)

        val vendorService = repositoryFactory.createVendorService(principal.projectId)
        val newStatus = runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorStatus.valueOf(request.status.uppercase()) }
            .getOrElse { throw IllegalArgumentException("Invalid status: '${request.status}'") }

        return when (val res = vendorService.updateStatus(
            projectId = principal.projectId,
            vendorId = vendorId,
            newStatus = newStatus,
            updatedBy = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDetailDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

    suspend fun listVendors(
        principal: AuthenticatedPrincipal,
        typeStr: String? = null,
        categoryStr: String? = null,
        statusStr: String? = null
    ): List<VendorSummaryDto> {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)

        val vendorService = repositoryFactory.createVendorService(principal.projectId)
        val type = typeStr?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorType.valueOf(it.uppercase()) }.getOrNull() }
        val category = categoryStr?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorCategory.valueOf(it.uppercase()) }.getOrNull() }
        val status = statusStr?.let { runCatching { com.sucharu.sucharupro.domain.model.vendor.VendorStatus.valueOf(it.uppercase()) }.getOrNull() }

        return when (val res = vendorService.listVendors(
            projectId = principal.projectId,
            type = type,
            category = category,
            status = status
        )) {
            is DomainResult.Success -> res.data.map { it.toSummaryDto() }
            is DomainResult.Error -> throw IllegalStateException(res.message)
            DomainResult.Loading -> emptyList()
        }
    }

