    suspend fun createVendorRate(
        principal: AuthenticatedPrincipal,
        vendorId: String,
        request: CreateVendorServiceRateRequestDto
    ): VendorServiceRateDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val rateService = repositoryFactory.createVendorServiceRateService(principal.projectId)

        val capabilityType = runCatching { com.sucharu.sucharupro.domain.model.vendor.CapabilityType.valueOf(request.capabilityType.uppercase()) }
            .getOrElse { throw IllegalArgumentException("Invalid capabilityType: '${request.capabilityType}'") }

        val pricingMethod = runCatching { com.sucharu.sucharupro.domain.model.vendor.PricingMethod.valueOf(request.pricingMethod.uppercase()) }
            .getOrElse { throw IllegalArgumentException("Invalid pricingMethod: '${request.pricingMethod}'") }

        val unitOfMeasure = runCatching { com.sucharu.sucharupro.domain.model.vendor.UnitOfMeasure.valueOf(request.unitOfMeasure.uppercase()) }
            .getOrElse { throw IllegalArgumentException("Invalid unitOfMeasure: '${request.unitOfMeasure}'") }

        val status = runCatching { com.sucharu.sucharupro.domain.model.vendor.RateStatus.valueOf(request.status.uppercase()) }
            .getOrElse { com.sucharu.sucharupro.domain.model.vendor.RateStatus.ACTIVE }

        val tiers = request.tiers.mapIndexed { idx, t ->
            com.sucharu.sucharupro.domain.model.vendor.VendorServiceRateTier(
                tierId = "",
                projectId = principal.projectId,
                rateId = "",
                minimumQuantity = java.math.BigDecimal.valueOf(t.minimumQuantity),
                maximumQuantity = t.maximumQuantity?.let { java.math.BigDecimal.valueOf(it) },
                rateAmount = com.sucharu.sucharupro.domain.model.common.Money(t.rateAmount)
            )
        }

        return when (val res = rateService.createRate(
            projectId = principal.projectId,
            vendorId = vendorId,
            capabilityType = capabilityType,
            serviceName = request.serviceName,
            rateCode = request.rateCode,
            pricingMethod = pricingMethod,
            unitOfMeasure = unitOfMeasure,
            rateAmount = com.sucharu.sucharupro.domain.model.common.Money(request.rateAmount),
            currency = request.currency,
            minimumQuantity = java.math.BigDecimal.valueOf(request.minimumQuantity),
            maximumQuantity = request.maximumQuantity?.let { java.math.BigDecimal.valueOf(it) },
            effectiveFrom = request.effectiveFrom,
            effectiveTo = request.effectiveTo,
            status = status,
            tiers = tiers,
            notes = request.notes,
            createdBy = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

