    suspend fun estimateVendorCost(
        principal: AuthenticatedPrincipal,
        rateId: String,
        request: EstimateVendorCostRequestDto
    ): EstimateVendorCostResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val rateService = repositoryFactory.createVendorServiceRateService(principal.projectId)
        val rate = when (val rRes = rateService.getRateById(principal.projectId, rateId)) {
            is DomainResult.Success -> rRes.data
            is DomainResult.Error -> throw NoSuchElementException(rRes.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }

        val estimated = when (val res = rateService.estimateCost(
            projectId = principal.projectId,
            rateId = rateId,
            quantity = java.math.BigDecimal.valueOf(request.quantity),
            areaSqFt = request.areaSqFt?.let { java.math.BigDecimal.valueOf(it) },
            weightKg = request.weightKg?.let { java.math.BigDecimal.valueOf(it) },
            durationHours = request.durationHours?.let { java.math.BigDecimal.valueOf(it) }
        )) {
            is DomainResult.Success -> res.data
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }

        return EstimateVendorCostResponseDto(
            rateId = rateId,
            estimatedCost = estimated.amount.toDouble(),
            formatted = estimated.formatted(),
            currency = rate.currency
        )
    }

