                itemDescription = itemDto.itemDescription,
                itemCode = itemDto.itemCode,
                orderedQuantity = java.math.BigDecimal.valueOf(itemDto.orderedQuantity),
                previouslyReceivedQuantity = java.math.BigDecimal.valueOf(itemDto.previouslyReceivedQuantity),
                receivedQuantity = java.math.BigDecimal.valueOf(itemDto.receivedQuantity),
