    ): VendorInvoiceDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val invoiceService = repositoryFactory.createVendorInvoiceService(principal.projectId)

        val items = request.items?.mapIndexed { idx, itm ->
            com.sucharu.sucharupro.domain.model.vendor.VendorInvoiceItem(
                itemId = "vii_${java.util.UUID.randomUUID().toString().replace("-", "").take(12)}",
                invoiceId = invoiceId,
                purchaseOrderItemId = itm.purchaseOrderItemId,
                deliveryReceiptItemId = itm.deliveryReceiptItemId,
                description = itm.description,
                quantity = java.math.BigDecimal.valueOf(itm.quantity),
                unitPrice = com.sucharu.sucharupro.domain.model.common.Money(itm.unitPrice),
                taxRate = java.math.BigDecimal.valueOf(itm.taxRate),
                taxAmount = com.sucharu.sucharupro.domain.model.common.Money(itm.taxAmount),
                discountAmount = com.sucharu.sucharupro.domain.model.common.Money(itm.discountAmount),
                sequence = idx + 1
            )
        }

        return when (val res = invoiceService.updateDraft(
            projectId = principal.projectId,
            invoiceId = invoiceId,
            vendorInvoiceNumber = request.vendorInvoiceNumber,
            invoiceDate = request.invoiceDate,
            shippingAmount = request.shippingAmount?.let { com.sucharu.sucharupro.domain.model.common.Money(it) },
            otherCharges = request.otherCharges?.let { com.sucharu.sucharupro.domain.model.common.Money(it) },
            notes = request.notes,
            items = items,
            actorId = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

