    suspend fun createVendorQualityInspection(
        principal: AuthenticatedPrincipal,
        request: CreateVendorQualityInspectionRequestDto
    ): VendorQualityInspectionDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val qualityService = repositoryFactory.createVendorQualityService(principal.projectId)
        val inspectionId = "VQI-${java.util.UUID.randomUUID()}"

        val items = request.items.map { itemReq ->
            com.sucharu.sucharupro.domain.model.vendor.VendorQualityInspectionItem(
                inspectionItemId = "VQII-${java.util.UUID.randomUUID()}",
                inspectionId = inspectionId,
                purchaseOrderItemId = itemReq.purchaseOrderItemId,
                deliveryReceiptItemId = itemReq.deliveryReceiptItemId,
                itemDescription = itemReq.itemDescription,
                receivedQuantity = java.math.BigDecimal(itemReq.receivedQuantity.toString()),
                acceptedQuantity = java.math.BigDecimal(itemReq.acceptedQuantity.toString()),
                rejectedQuantity = java.math.BigDecimal(itemReq.rejectedQuantity.toString()),
                conditionalQuantity = java.math.BigDecimal(itemReq.conditionalQuantity.toString()),
                defectCount = itemReq.defectCount,
                inspectionResult = com.sucharu.sucharupro.domain.model.vendor.InspectionResult.valueOf(itemReq.inspectionResult),
                notes = itemReq.notes
            )
        }

        val inspection = com.sucharu.sucharupro.domain.model.vendor.VendorQualityInspection(
            inspectionId = inspectionId,
            projectId = principal.projectId,
            tenantId = principal.projectId,
            vendorId = request.vendorId,
            purchaseOrderId = request.purchaseOrderId,
            deliveryReceiptId = request.deliveryReceiptId,
            inspectionReference = request.inspectionReference,
            inspectionType = com.sucharu.sucharupro.domain.model.vendor.VendorInspectionType.valueOf(request.inspectionType),
            inspectionStatus = com.sucharu.sucharupro.domain.model.vendor.VendorInspectionStatus.DRAFT,
            receivedQuantity = java.math.BigDecimal(request.receivedQuantity.toString()),
            notes = request.notes,
            items = items,
            createdBy = principal.userId,
            updatedBy = principal.userId
        )

        return when (val res = qualityService.createInspection(inspection, principal.userId)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

