    suspend fun updateVendorQualityInspection(
        principal: AuthenticatedPrincipal,
        inspectionId: String,
        request: UpdateVendorQualityInspectionRequestDto
    ): VendorQualityInspectionDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val qualityService = repositoryFactory.createVendorQualityService(principal.projectId)
        val existing = when (val res = qualityService.getInspection(principal.projectId, inspectionId)) {
            is DomainResult.Success -> res.data
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
        val updated = existing.copy(
            notes = request.notes ?: existing.notes,
            overallResult = request.overallResult?.let { com.sucharu.sucharupro.domain.model.vendor.InspectionResult.valueOf(it) } ?: existing.overallResult
        )
        return when (val res = qualityService.updateInspection(updated, principal.userId)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

