            kpiId = "KPI-${java.util.UUID.randomUUID()}",
            projectId = principal.projectId,
            tenantId = principal.projectId,
            code = request.code,
            name = request.name,
            description = request.description,
            kpiType = com.sucharu.sucharupro.domain.model.vendor.KpiType.valueOf(request.kpiType),
            measurementMethod = com.sucharu.sucharupro.domain.model.vendor.KpiMeasurementMethod.valueOf(request.measurementMethod),
            targetValue = request.targetValue,
            minimumAcceptableValue = request.minimumAcceptableValue,
            maximumAcceptableValue = request.maximumAcceptableValue,
            unit = request.unit,
            direction = com.sucharu.sucharupro.domain.model.vendor.KpiDirection.valueOf(request.direction),
            weight = request.weight,
            effectiveFrom = request.effectiveFrom?.let { java.time.Instant.ofEpochMilli(it) } ?: java.time.Instant.now(),
            effectiveTo = request.effectiveTo?.let { java.time.Instant.ofEpochMilli(it) },
            createdBy = principal.userId
        )
        return when (val res = service.createKpi(kpi)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

    suspend fun updateVendorPerformanceKpi(
        principal: AuthenticatedPrincipal,
        kpiId: String,
        request: UpdateVendorPerformanceKpiRequestDto
    ): VendorPerformanceKpiDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createVendorPerformanceService(principal.projectId)
        val existingRes = service.getKpiById(principal.projectId, kpiId)
        if (existingRes !is DomainResult.Success) throw NoSuchElementException("KPI '$kpiId' not found")
        val existing = existingRes.data

        val updated = existing.copy(
            name = request.name ?: existing.name,
            description = request.description ?: existing.description,
            targetValue = request.targetValue ?: existing.targetValue,
            minimumAcceptableValue = request.minimumAcceptableValue ?: existing.minimumAcceptableValue,
            maximumAcceptableValue = request.maximumAcceptableValue ?: existing.maximumAcceptableValue,
            weight = request.weight ?: existing.weight,
            status = request.status?.let { com.sucharu.sucharupro.domain.model.vendor.KpiStatus.valueOf(it) } ?: existing.status,
            effectiveTo = request.effectiveTo?.let { java.time.Instant.ofEpochMilli(it) } ?: existing.effectiveTo,
            version = existing.version + 1,
            updatedAt = java.time.Instant.now(),
            updatedBy = principal.userId
        )
        return when (val res = service.updateKpi(updated)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

