    // --- Evaluations ---
    suspend fun createVendorEvaluation(
        principal: AuthenticatedPrincipal,
        vendorId: String,
        request: CreateVendorEvaluationRequestDto
    ): VendorEvaluationDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createVendorPerformanceService(principal.projectId)
        val evalId = "EVAL-${java.util.UUID.randomUUID()}"
        val periodType = com.sucharu.sucharupro.domain.model.vendor.EvaluationPeriodType.valueOf(request.periodType)
        val pStart = java.time.Instant.ofEpochMilli(request.periodStart)
        val pEnd = java.time.Instant.ofEpochMilli(request.periodEnd)

        val criteria = request.criteria.map { c ->
            com.sucharu.sucharupro.domain.model.vendor.VendorEvaluationCriterion(
                criterionId = c.criterionId.ifBlank { "CRIT-${java.util.UUID.randomUUID()}" },
                evaluationId = evalId,
                name = c.name,
                category = c.category,
                weight = c.weight,
                score = c.score,
                comments = c.comments
            )
        }

        var totalWeight = 0.0
        var totalWeightedScore = 0.0
        for (c in criteria) {
            totalWeight += c.weight
            totalWeightedScore += c.score * c.weight
        }
        val computedScore = if (totalWeight > 0.0) totalWeightedScore / totalWeight else 0.0
        val rating = com.sucharu.sucharupro.domain.service.vendor.VendorPerformanceCalculator.mapScoreToRating(computedScore)

        val evaluation = com.sucharu.sucharupro.domain.model.vendor.VendorEvaluation(
            evaluationId = evalId,
            projectId = principal.projectId,
            tenantId = principal.projectId,
            vendorId = vendorId,
            scorecardId = request.scorecardId,
            periodType = periodType,
            periodStart = pStart,
            periodEnd = pEnd,
            evaluatorId = principal.userId,
            evaluatorName = principal.username,
            evaluationScore = com.sucharu.sucharupro.domain.service.vendor.VendorPerformanceCalculator.round(computedScore),
            rating = rating,
            evaluatorComments = request.evaluatorComments,
            criteria = criteria,
            createdBy = principal.userId
        )

        return when (val res = service.createEvaluation(evaluation)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

