    // --- Compliance Records ---
    suspend fun submitVendorComplianceRecord(
        principal: AuthenticatedPrincipal,
        vendorId: String,
        request: SubmitVendorComplianceRecordRequestDto
    ): VendorComplianceRecordDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createVendorPerformanceService(principal.projectId)
        val reqRes = service.getComplianceRequirementById(principal.projectId, request.requirementId)
        if (reqRes !is DomainResult.Success) throw NoSuchElementException("Compliance requirement '${request.requirementId}' not found")
        val req = reqRes.data

        val recordId = "COMP-REC-${java.util.UUID.randomUUID()}"
        val evidence = request.evidenceList.map { ev ->
            com.sucharu.sucharupro.domain.model.vendor.VendorComplianceEvidence(
                evidenceId = ev.evidenceId.ifBlank { "EVD-${java.util.UUID.randomUUID()}" },
                recordId = recordId,
                projectId = principal.projectId,
                tenantId = principal.projectId,
                evidenceType = com.sucharu.sucharupro.domain.model.vendor.ComplianceEvidenceType.valueOf(ev.evidenceType),
                fileName = ev.fileName,
                fileUrl = ev.fileUrl,
                checksum = ev.checksum,
                fileSizeBytes = ev.fileSizeBytes,
                mimeType = ev.mimeType,
                uploadedBy = principal.userId
            )
        }

        val effDate = request.effectiveDate?.let { java.time.Instant.ofEpochMilli(it) } ?: java.time.Instant.now()
        val expDate = request.expiryDate?.let { java.time.Instant.ofEpochMilli(it) }
            ?: (if (req.validityDays != null) effDate.plus(req.validityDays.toLong(), java.time.temporal.ChronoUnit.DAYS) else null)

        val record = com.sucharu.sucharupro.domain.model.vendor.VendorComplianceRecord(
            recordId = recordId,
            projectId = principal.projectId,
            tenantId = principal.projectId,
            vendorId = vendorId,
            requirementId = req.requirementId,
            requirementCode = req.code,
            requirementName = req.name,
            requirementType = req.requirementType,
            mandatory = req.mandatory,
            effectiveDate = effDate,
            expiryDate = expDate,
            notes = request.notes,
            evidenceList = evidence,
            createdBy = principal.userId
        )

        return when (val res = service.submitComplianceRecord(record)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

