    suspend fun createVendorSettlement(
        principal: AuthenticatedPrincipal,
        request: CreateVendorSettlementRequestDto
    ): VendorSettlementDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createVendorSettlementService(principal.projectId)
        val allocs = request.allocations.map {
            com.sucharu.sucharupro.domain.model.vendor.VendorSettlementAllocation(
                allocationId = "",
                settlementId = "",
                payableId = it.payableId,
                invoiceId = it.invoiceId,
                allocatedAmount = com.sucharu.sucharupro.domain.model.common.Money(it.allocatedAmount),
                currency = it.currency
            )
        }
        val sMethod = try {
            com.sucharu.sucharupro.domain.model.vendor.SettlementMethod.valueOf(request.settlementMethod)
        } catch (_: Exception) {
            com.sucharu.sucharupro.domain.model.vendor.SettlementMethod.BANK_TRANSFER
        }
        return when (val res = service.createSettlement(
            vendorId = request.vendorId,
            settlementNumber = request.settlementNumber,
            totalAmount = com.sucharu.sucharupro.domain.model.common.Money(request.totalAmount),
            settlementMethod = sMethod,
            referenceNumber = request.referenceNumber,
            notes = request.notes,
            allocations = allocs,
            tenantId = principal.projectId,
            projectId = principal.projectId,
            actorId = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

