    // 23. VENDOR RFQ / QUOTATION & BID MANAGEMENT USE CASES (Step 03)
    // =========================================================================

    suspend fun createVendorRfq(
        principal: AuthenticatedPrincipal,
        request: CreateVendorRfqRequestDto
    ): VendorRfqDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createVendorRfqService(principal.projectId)
        val rfqId = UUID.randomUUID().toString()
        val rfqNumber = request.rfqNumber ?: "RFQ-${System.currentTimeMillis().toString().takeLast(6)}"

        val items = request.items.mapIndexed { idx, itemDto ->
            com.sucharu.sucharupro.domain.model.vendorportal.VendorRfqItem(
                rfqItemId = UUID.randomUUID().toString(),
                rfqId = rfqId,
                sequenceNumber = if (itemDto.sequenceNumber > 0) itemDto.sequenceNumber else idx + 1,
                itemCode = itemDto.itemCode,
                description = itemDto.description,
                requiredCapabilityType = itemDto.requiredCapabilityType,
                quantity = BigDecimal.valueOf(itemDto.quantity),
                unitOfMeasure = itemDto.unitOfMeasure,
                targetUnitPrice = itemDto.targetUnitPrice?.let { Money(BigDecimal.valueOf(it)) },
