    // Quotation Operations

    suspend fun createVendorPortalQuotation(
        principal: AuthenticatedPrincipal,
        rfqId: String,
        request: CreateVendorQuotationRequestDto
    ): VendorQuotationDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.VENDOR, UserRole.AI_AGENT)
        val vendorId = principal.effectiveVendorId
            ?: throw IllegalArgumentException("Authenticated principal has no associated vendor identity")
        val quotationService = repositoryFactory.createVendorQuotationService(principal.projectId)
        val quotationId = UUID.randomUUID().toString()
        val quotationNumber = request.quotationNumber ?: "QTN-${System.currentTimeMillis().toString().takeLast(6)}"

        val items = request.items.map { itemDto ->
            com.sucharu.sucharupro.domain.model.vendorportal.VendorQuotationItem(
                quotationItemId = UUID.randomUUID().toString(),
                quotationId = quotationId,
                rfqItemId = itemDto.rfqItemId,
                quantity = BigDecimal.valueOf(itemDto.quantity),
                unitPrice = Money(BigDecimal.valueOf(itemDto.unitPrice)),
                discountAmount = Money(BigDecimal.valueOf(itemDto.discountAmount)),
                taxAmount = Money(BigDecimal.valueOf(itemDto.taxAmount)),
                lineTotal = Money.ZERO, // Will be computed deterministically
                deliveryLeadTimeDays = itemDto.deliveryLeadTimeDays,
                notes = itemDto.notes
            )
        }

        val quotation = com.sucharu.sucharupro.domain.model.vendorportal.VendorQuotation(
            quotationId = quotationId,
            rfqId = rfqId,
            invitationId = "", // Checked and bound in service
            vendorId = vendorId,
            projectId = principal.projectId,
            tenantId = principal.projectId,
            quotationNumber = quotationNumber,
            vendorReferenceNumber = request.vendorReferenceNumber,
            currency = request.currency,
            validityPeriodDays = request.validityPeriodDays,
            paymentTerms = request.paymentTerms,
            deliveryLeadTimeDays = request.deliveryLeadTimeDays,
            shippingTerms = request.shippingTerms,
            notes = request.notes,
            items = items,
            createdBy = principal.userId
        )

        return when (val res = quotationService.createQuotationDraft(quotation, principal.projectId, principal.userId)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

    suspend fun getVendorPortalQuotation(
        principal: AuthenticatedPrincipal,
        quotationId: String
    ): VendorQuotationDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.VENDOR, UserRole.AI_AGENT)
        val quotationService = repositoryFactory.createVendorQuotationService(principal.projectId)
        return if (principal.role == UserRole.VENDOR) {
            val vendorId = principal.effectiveVendorId ?: throw IllegalArgumentException("Missing vendor ID")
            when (val res = quotationService.getQuotationForVendor(quotationId, vendorId, principal.projectId)) {
                is DomainResult.Success -> res.data.toDto()
                is DomainResult.Error -> throw IllegalArgumentException(res.message)
                DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
            }
        } else {
            when (val res = quotationService.getQuotationById(quotationId, principal.projectId)) {
                is DomainResult.Success -> res.data.toDto()
                is DomainResult.Error -> throw IllegalArgumentException(res.message)
                DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
            }
        }
    }

