    suspend fun recordVendorRfqEvaluation(
        principal: AuthenticatedPrincipal,
        rfqId: String,
        request: RecordEvaluationRequestDto
    ): VendorRfqEvaluationDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createVendorRfqEvaluationService(principal.projectId)

        val scores = request.scores.map { sDto ->
            com.sucharu.sucharupro.domain.model.vendorportal.VendorRfqEvaluationScore(
                criterion = sDto.criterion,
                weightPercent = sDto.weightPercent,
                rawScore = sDto.rawScore,
                weightedScore = 0.0,
                evaluatorNotes = sDto.evaluatorNotes
            )
        }

        val decision = com.sucharu.sucharupro.domain.model.vendorportal.VendorRfqEvaluationDecision.valueOf(request.decision.uppercase())

        val evaluation = com.sucharu.sucharupro.domain.model.vendorportal.VendorRfqEvaluation(
            evaluationId = UUID.randomUUID().toString(),
            rfqId = rfqId,
            quotationId = request.quotationId,
            vendorId = "", // Bound in service
            tenantId = principal.projectId,
            projectId = principal.projectId,
            evaluatorUserId = principal.userId,
            scores = scores,
            decision = decision,
            remarks = request.remarks
        )

        return when (val res = service.recordEvaluation(evaluation, principal.projectId, principal.userId)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
