    suspend fun createVendorPortalInvoiceSubmission(
        principal: AuthenticatedPrincipal,
        request: SubmitVendorInvoiceRequestDto
    ): VendorPortalInvoiceSubmissionDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.VENDOR, UserRole.AI_AGENT)
        val vendorId = principal.effectiveVendorId
            ?: throw IllegalArgumentException("Authenticated principal has no associated vendor identity")
        val service = repositoryFactory.createVendorPortalInvoiceService(principal.projectId)
        val itemsInput = request.items.map { item ->
            com.sucharu.sucharupro.domain.model.vendorportal.VendorPortalInvoiceSubmissionItemInput(
                purchaseOrderItemId = item.purchaseOrderItemId,
                deliveryReceiptItemId = item.deliveryReceiptItemId,
                invoicedQuantity = java.math.BigDecimal.valueOf(item.invoicedQuantity),
                unitPrice = item.unitPrice?.let { com.sucharu.sucharupro.domain.model.common.Money(java.math.BigDecimal.valueOf(it)) },
                taxAmount = item.taxAmount?.let { com.sucharu.sucharupro.domain.model.common.Money(java.math.BigDecimal.valueOf(it)) },
                remarks = item.remarks
            )
        }
        return when (val res = service.createInvoiceSubmission(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            vendorId = vendorId,
            purchaseOrderId = request.purchaseOrderId,
            vendorInvoiceNumber = request.vendorInvoiceNumber,
            invoiceDate = request.invoiceDate,
            currency = request.currency,
            shippingAmount = request.shippingAmount?.let { java.math.BigDecimal.valueOf(it) },
            otherCharges = request.otherCharges?.let { java.math.BigDecimal.valueOf(it) },
            notes = request.notes,
            items = itemsInput,
            actorId = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

