    suspend fun updateCustomerFinancialAccountStatus(
        principal: AuthenticatedPrincipal,
        financialAccountId: String,
        request: UpdateCustomerFinancialAccountStatusRequest
    ): CustomerFinancialAccountDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createCustomerFinancialAccountService(principal.projectId)
        val targetStatus = com.sucharu.sucharupro.domain.model.customerfinancial.CustomerFinancialAccountStatus.valueOf(request.status)
        val res = when (targetStatus) {
            com.sucharu.sucharupro.domain.model.customerfinancial.CustomerFinancialAccountStatus.SUSPENDED ->
                service.suspendAccount(
                    principal.projectId, principal.projectId, financialAccountId,
                    request.reason ?: "", principal.userId, principal.role.name, request.expectedVersion
                )
            com.sucharu.sucharupro.domain.model.customerfinancial.CustomerFinancialAccountStatus.ACTIVE ->
                service.reactivateAccount(
                    principal.projectId, principal.projectId, financialAccountId,
                    request.reason, principal.userId, principal.role.name, request.expectedVersion
                )
            com.sucharu.sucharupro.domain.model.customerfinancial.CustomerFinancialAccountStatus.CLOSED ->
                service.closeAccount(
                    principal.projectId, principal.projectId, financialAccountId,
                    request.reason ?: "", principal.userId, principal.role.name, request.expectedVersion
                )
        }
        return when (res) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

