    suspend fun createCustomerCollectionAction(
        principal: AuthenticatedPrincipal,
        customerId: String,
        request: CreateCustomerCollectionActionRequest
    ): CustomerCollectionActionDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createCustomerCollectionService(principal.projectId)
        val actionType = try {
            com.sucharu.sucharupro.domain.model.customercollection.CollectionActionType.valueOf(request.actionType)
        } catch (e: Exception) {
            com.sucharu.sucharupro.domain.model.customercollection.CollectionActionType.REMINDER
        }
        val priority = request.priority?.let {
            try { com.sucharu.sucharupro.domain.model.customercollection.CollectionPriority.valueOf(it) } catch (e: Exception) { null }
        }
        return when (val res = service.createCollectionAction(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            customerId = customerId,
            invoiceId = request.invoiceId,
            actionType = actionType,
            priority = priority,
            scheduledAt = request.scheduledAt,
            nextFollowUpAt = request.nextFollowUpAt,
            assignedUserId = request.assignedUserId,
            notes = request.notes,
            idempotencyKey = request.idempotencyKey,
            actorId = principal.userId,
            actorRole = principal.role.name
