    suspend fun exportCustomerFinancialReport(
        principal: AuthenticatedPrincipal,
        customerId: String,
        request: ExportCustomerFinancialReportRequest
    ): CustomerFinancialGeneratedDocumentDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.CUSTOMER)
        if (principal.role == UserRole.CUSTOMER) {
            BackendAuthorizationPolicy.enforceCustomerOwnership(principal, customerId)
        }
        val reportType = try {
            com.sucharu.sucharupro.domain.model.customerfinancialreporting.CustomerFinancialReportType.valueOf(request.reportType.uppercase())
        } catch (e: Exception) {
            throw IllegalArgumentException("Unsupported report type: ${request.reportType}")
        }
        val format = try {
            com.sucharu.sucharupro.domain.model.customerfinancialreporting.CustomerFinancialReportFormat.valueOf(request.format.uppercase())
        } catch (e: Exception) {
            throw IllegalArgumentException("Unsupported report format: ${request.format}")
        }

        val reportReq = com.sucharu.sucharupro.domain.model.customerfinancialreporting.CustomerFinancialReportRequest(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            customerId = customerId,
            reportType = reportType,
            format = format,
            fromDate = request.fromDate,
            toDate = request.toDate,
            invoiceId = request.invoiceId,
            requestedBy = principal.userId
        )

        val service = repositoryFactory.createCustomerFinancialReportingService(principal.projectId)
        return when (val res = service.exportFinancialReport(reportReq)) {
