    suspend fun createBusinessExpense(
        principal: AuthenticatedPrincipal,
        request: CreateBusinessExpenseRequest,
        idempotencyKey: String? = null
    ): BusinessExpenseDto {
        val service = repositoryFactory.createBusinessExpenseService(principal.projectId)
        val amountDec = try {
            java.math.BigDecimal(request.amount)
        } catch (e: Exception) {
            throw ValidationException("Invalid monetary amount '${request.amount}'.")
        }
        val paymentMethod = try {
            com.sucharu.sucharupro.domain.model.businessexpense.BusinessExpensePaymentMethod.valueOf(request.paymentMethod.uppercase())
        } catch (e: Exception) {
            throw ValidationException("Unsupported payment method '${request.paymentMethod}'.")
        }

        val command = com.sucharu.sucharupro.domain.service.businessexpense.CreateBusinessExpenseCommand(
            categoryId = request.categoryId,
            amount = amountDec,
            currency = request.currency,
            expenseDate = request.expenseDate ?: System.currentTimeMillis(),
            paymentMethod = paymentMethod,
            paymentReference = request.paymentReference,
            vendorId = request.vendorId,
            jobId = request.jobId,
            branchId = request.branchId,
            locationId = request.locationId,
            description = request.description,
            notes = request.notes,
            attachmentUrl = request.attachmentUrl,
            attachmentMetadata = request.attachmentMetadata,
            idempotencyKey = idempotencyKey,
            autoSubmit = request.autoSubmit
        )

        return when (val res = service.createExpense(principal, command)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw ValidationException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

    suspend fun updateBusinessExpense(
        principal: AuthenticatedPrincipal,
        expenseId: String,
        request: UpdateBusinessExpenseRequest
    ): BusinessExpenseDto {
        val service = repositoryFactory.createBusinessExpenseService(principal.projectId)
        val amountDec = request.amount?.let {
            try {
                java.math.BigDecimal(it)
            } catch (e: Exception) {
                throw ValidationException("Invalid monetary amount '$it'.")
            }
        }
        val paymentMethod = request.paymentMethod?.let {
            try {
                com.sucharu.sucharupro.domain.model.businessexpense.BusinessExpensePaymentMethod.valueOf(it.uppercase())
            } catch (e: Exception) {
                throw ValidationException("Unsupported payment method '$it'.")
            }
        }

        val command = com.sucharu.sucharupro.domain.service.businessexpense.UpdateBusinessExpenseCommand(
            categoryId = request.categoryId,
            amount = amountDec,
            currency = request.currency,
            expenseDate = request.expenseDate,
            paymentMethod = paymentMethod,
            paymentReference = request.paymentReference,
            vendorId = request.vendorId,
            jobId = request.jobId,
            branchId = request.branchId,
            locationId = request.locationId,
            description = request.description,
            notes = request.notes,
            attachmentUrl = request.attachmentUrl,
            attachmentMetadata = request.attachmentMetadata
        )

        return when (val res = service.updateExpenseDraft(principal, expenseId, command)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw ValidationException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

