        limit: Int = 50,
        offset: Int = 0
    ): List<BusinessLedgerPostingDto> {
        val service = repositoryFactory.createBusinessLedgerService(principal.projectId)
        val sType = sourceType?.let {
            try { com.sucharu.sucharupro.domain.model.businessledger.BusinessLedgerSourceType.valueOf(it) } catch (e: Exception) { null }
        }
        val pType = postingType?.let {
            try { com.sucharu.sucharupro.domain.model.businessledger.BusinessLedgerPostingType.valueOf(it) } catch (e: Exception) { null }
        }
        val aCategory = accountCategory?.let {
            try { com.sucharu.sucharupro.domain.model.businessledger.BusinessLedgerAccountCategory.valueOf(it) } catch (e: Exception) { null }
        }

        val filter = com.sucharu.sucharupro.data.datasource.businessledger.BusinessLedgerPostingFilter(
            sourceType = sType,
            sourceId = sourceId,
            postingType = pType,
            accountCategory = aCategory,
            jobId = jobId,
            vendorId = vendorId,
            expenseId = expenseId,
            payableId = payableId,
            fromDate = fromDate,
            toDate = toDate,
            isReversed = isReversed,
            limit = limit,
