    private fun handleDomainError(res: DomainResult.Error): Nothing {
        val msg = res.message
        if (msg.contains("Access denied", ignoreCase = true) ||
            msg.contains("Forbidden", ignoreCase = true) ||
            msg.contains("not authorized", ignoreCase = true)
        ) {
            throw com.sucharu.sucharupro.data.api.model.ForbiddenException(msg)
        } else {
            throw ValidationException(msg)
        }
    }

