    suspend fun getExecutiveFinancialSummary(
        principal: AuthenticatedPrincipal,
        periodId: String? = null,
        currency: String = "BDT"
    ): BusinessExecutiveFinancialSummaryDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createBusinessFinancialReportingService(principal.projectId)
        val filter = BusinessFinancialReportFilter(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            reportType = BusinessFinancialReportType.EXECUTIVE_SUMMARY,
            periodId = periodId,
            currency = currency,
            requestedBy = principal.userId
        )
        val summary = service.generateExecutiveSummary(filter)
        return summary.toDto()
    }

