    suspend fun generateDeterministicForecast(
        principal: AuthenticatedPrincipal,
        request: GenerateForecastRequestDto
    ): BusinessFinancialForecastDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createBusinessFinancialGovernanceService(principal.projectId)
        return when (val res = service.generateDeterministicForecast(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            periodId = request.periodId,
            dimensionType = request.dimensionType,
            dimensionId = request.dimensionId,
            currency = request.currency,
            actorId = principal.userId
        )) {
            is DomainResult.Success -> {
                val (forecast, scenarios) = res.data
                forecast.toDto(scenarios.map { it.toDto() })
            }
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

