        val list = (service.listForecasts(principal.projectId, principal.projectId, periodId) as? DomainResult.Success)?.data ?: emptyList()
        return list.map { f ->
            val scenarios = (service.getForecastScenarios(principal.projectId, principal.projectId, f.id) as? DomainResult.Success)?.data ?: emptyList()
            f.toDto(scenarios.map { it.toDto() })
        }
    }

