    suspend fun executeBusinessFinancialIntegrityRun(
        principal: AuthenticatedPrincipal,
        request: ExecuteIntegrityRunRequestDto
    ): FinancialIntegrityRunDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createBusinessFinancialIntegrityService(principal.projectId)
        return when (val res = service.executeIntegrityRun(
