            customRevenue = request.customRevenue,
            customDirectCost = request.customDirectCost,
            customIndirectCost = request.customIndirectCost,
            baselineCost = request.baselineCost,
            baselineRevenue = request.baselineRevenue,
            revenueProvenances = request.revenueProvenances.map { it.toDomain(principal.projectId, principal.projectId) },
            costAttributions = request.costAttributions.map { it.toDomain(principal.projectId, principal.projectId) },
            idempotencyKey = request.idempotencyKey,
            actor = principal.userId
