    suspend fun calculateJobActualCost(
        principal: AuthenticatedPrincipal,
        jobId: String,
        req: CalculateJobCostRequestDto
    ): JobCostSnapshotDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createJobCostCalculationService(principal.projectId)
        val customEst = req.customEstimatedCost?.let { java.math.BigDecimal.valueOf(it).setScale(4, java.math.RoundingMode.HALF_UP) }

        return when (val res = service.calculateJobActualCost(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            jobId = jobId,
            jobNumber = req.jobNumber,
            customerId = req.customerId,
            productId = req.productId,
            jobQuantity = req.jobQuantity,
            customEstimatedCost = customEst,
            idempotencyKey = req.idempotencyKey,
            actor = principal.username
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

