    suspend fun reconcileJobActualCost(
        principal: AuthenticatedPrincipal,
        jobId: String
    ): JobCostReconciliationEventDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createJobCostCalculationService(principal.projectId)
        val snapRes = service.getJobActualCostSnapshot(principal.projectId, principal.projectId, jobId)
        if (snapRes is DomainResult.Error) {
            throw IllegalArgumentException(snapRes.message)
        }
        val snapshot = (snapRes as DomainResult.Success).data
        return when (val res = service.reconcileJobCost(principal.projectId, principal.projectId, snapshot.snapshotId, principal.username)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

