    suspend fun calculateProductProfitability(
        principal: AuthenticatedPrincipal,
        productId: String,
        req: CalculateProductProfitabilityRequestDto
    ): ProductProfitabilitySnapshotDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createProductProfitabilityService(principal.projectId)
        val customRev = req.customRevenue?.map { r ->
            ProductRevenueAttribution(
                revenueAttributionId = r.revenueAttributionId,
                tenantId = principal.projectId,
                projectId = principal.projectId,
                productId = r.productId,
                sku = r.sku,
                editionId = r.editionId,
                versionId = r.versionId,
                invoiceId = r.invoiceId,
                orderId = r.orderId,
                customerId = r.customerId,
                quantity = r.quantity,
                recognizedRevenue = r.recognizedRevenue,
                attributionRatio = r.attributionRatio,
                sourceModule = r.sourceModule,
                sourceEntityType = r.sourceEntityType,
                sourceEntityId = r.sourceEntityId,
                sourceTransactionId = r.sourceTransactionId,
                attributionMethod = r.attributionMethod,
                provenanceFingerprint = r.provenanceFingerprint
            )
        }
        val customCost = req.customCosts?.map { c ->
            ProductCostAttribution(
                costAttributionId = c.costAttributionId,
                tenantId = principal.projectId,
                projectId = principal.projectId,
                productId = c.productId,
                sku = c.sku,
                editionId = c.editionId,
                versionId = c.versionId,
                jobId = c.jobId,
                componentType = JobCostComponentType.valueOf(c.componentType),
                directness = CostDirectness.valueOf(c.directness),
                attributedAmount = c.attributedAmount,
                allocationBasis = ProductCostAllocationBasis.valueOf(c.allocationBasis),
                numerator = c.numerator,
                denominator = c.denominator,
                allocationRatio = c.allocationRatio,
                sourceModule = c.sourceModule,
                sourceEntityType = c.sourceEntityType,
                sourceEntityId = c.sourceEntityId,
                sourceTransactionId = c.sourceTransactionId,
                provenanceFingerprint = c.provenanceFingerprint
            )
        }

        return when (val res = service.calculateProductProfitability(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            productId = productId,
            sku = req.sku,
            productName = req.productName,
            editionId = req.editionId,
            versionId = req.versionId,
            periodId = req.periodId,
            customerId = req.customerId,
            customRevenue = customRev,
            customCosts = customCost,
            customBaselineCost = req.customBaselineCost,
            idempotencyKey = req.idempotencyKey,
            actor = principal.username
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

