    // --- Module 16 Step 04: Customer Profitability Use Cases ---

    suspend fun calculateCustomerProfitability(
        principal: AuthenticatedPrincipal,
        customerId: String,
        request: CalculateCustomerProfitabilityRequestDto
    ): CustomerProfitabilitySnapshotDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createCustomerProfitabilityService(principal.projectId)
        val pType = request.periodType?.let { ProfitabilityPeriodType.valueOf(it) } ?: ProfitabilityPeriodType.ALL_TIME

        val customRev = request.customRevenue?.map { dto ->
            CustomerRevenueAttribution(
                revenueAttributionId = dto.revenueAttributionId,
                tenantId = principal.projectId,
                projectId = principal.projectId,
                customerId = customerId,
                orderId = dto.orderId,
                invoiceId = dto.invoiceId,
                invoiceLineId = dto.invoiceLineId,
                productId = dto.productId,
                quantity = dto.quantity,
                recognizedRevenue = dto.recognizedRevenue,
                currency = dto.currency,
                sourceModule = dto.sourceModule,
                sourceEntityType = dto.sourceEntityType,
                sourceEntityId = dto.sourceEntityId,
                sourceTransactionId = dto.sourceTransactionId,
                provenanceFingerprint = dto.provenanceFingerprint
            )
        }

        val customCosts = request.customCosts?.map { dto ->
            CustomerCostAttribution(
                costAttributionId = dto.costAttributionId,
                tenantId = principal.projectId,
                projectId = principal.projectId,
                customerId = customerId,
                orderId = dto.orderId,
                jobId = dto.jobId,
                productId = dto.productId,
                componentType = JobCostComponentType.valueOf(dto.componentType),
                directness = CostDirectness.valueOf(dto.directness),
                isVariableCost = dto.isVariableCost,
                attributedAmount = dto.attributedAmount,
                allocationBasis = dto.allocationBasis,
                numerator = dto.numerator,
                denominator = dto.denominator,
                allocationRatio = dto.allocationRatio,
                priority = CustomerCostAttributionPriority.valueOf(dto.priority),
                sourceModule = dto.sourceModule,
                sourceEntityType = dto.sourceEntityType,
                sourceEntityId = dto.sourceEntityId,
                sourceTransactionId = dto.sourceTransactionId,
                provenanceFingerprint = dto.provenanceFingerprint
            )
        }

        return when (val res = service.calculateCustomerProfitability(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            customerId = customerId,
            customerName = request.customerName,
            customerCode = request.customerCode,
            periodType = pType,
            periodStart = request.periodStart,
            periodEnd = request.periodEnd,
            customRevenue = customRev,
            customCosts = customCosts,
            previousPeriodMargin = request.previousPeriodMargin,
            idempotencyKey = request.idempotencyKey,
            actor = principal.userId
        )) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message)
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

