        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
        val service = repositoryFactory.createProfitabilityForecastService(principal.projectId)
        val scope = ProfitabilityForecastScope.valueOf(request.targetScope.uppercase())
        val horizon = ForecastHorizon.valueOf(request.horizon.uppercase())
        val method = ProfitabilityForecastMethod.valueOf(request.forecastMethod.uppercase())
        val scenarioType = ProfitabilityScenarioType.valueOf(request.scenarioType.uppercase())

        return when (val res = service.generateForecast(
            tenantId = principal.projectId,
            projectId = principal.projectId,
            targetScope = scope,
            targetEntityId = request.targetEntityId,
            targetEntityLabel = request.targetEntityLabel,
            historicalPeriodStart = request.historicalPeriodStart,
            historicalPeriodEnd = request.historicalPeriodEnd,
            forecastPeriodStart = request.forecastPeriodStart,
            forecastPeriodEnd = request.forecastPeriodEnd,
            horizon = horizon,
            forecastMethod = method,
            scenarioType = scenarioType,
            scenarioId = request.scenarioId,
            idempotencyKey = request.idempotencyKey,
            actorId = principal.userId,
            actorRole = principal.role.name
        )) {
            is DomainResult.Success -> res.data.toDto()
