    suspend fun calculatePrintingQuote(
        principal: AuthenticatedPrincipal,
        requestDto: com.sucharu.sucharupro.data.api.model.printingquote.CalculatePrintingQuoteRequestDto
    ): com.sucharu.sucharupro.data.api.model.printingquote.PrintingQuoteVersionDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val quoteService = repositoryFactory.createPrintingQuoteService(principal.projectId)
        val calcService = repositoryFactory.createPrintingCalculatorService(principal.projectId)
        val quote = when (val qr = quoteService.getQuote(principal.projectId, requestDto.quoteId)) {
            is DomainResult.Success -> qr.data ?: throw NoSuchElementException("Quote not found: " + requestDto.quoteId)
            else -> throw IllegalArgumentException("Quote not found: " + requestDto.quoteId)
        }
        val step01 = when (val cr = calcService.getCalculationById(principal.projectId, quote.calculationId)) {
            is DomainResult.Success -> cr.data ?: throw NoSuchElementException("Calculation not found: " + quote.calculationId)
            else -> throw IllegalArgumentException("Step 01 calculation not found")
        }
        val domainRequest = buildPrintingQuoteCalculateRequest(requestDto, principal)
        return when (val res = quoteService.calculateQuote(domainRequest, step01)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message ?: "Failed to calculate quote")
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

