            is DomainResult.Success -> qr.data ?: throw NoSuchElementException("Quote not found: " + requestDto.quoteId)
            else -> throw IllegalArgumentException("Quote not found: " + requestDto.quoteId)
        }
        val step01 = when (val cr = calcService.getCalculationById(principal.projectId, quote.calculationId)) {
            is DomainResult.Success -> cr.data ?: throw NoSuchElementException("Calculation not found")
            else -> throw IllegalArgumentException("Step 01 calculation not found")
        }
        val domainRequest = buildPrintingQuoteCalculateRequest(requestDto, principal)
        return when (val res = quoteService.recalculateQuote(domainRequest, step01)) {
            is DomainResult.Success -> res.data.toDto()
            is DomainResult.Error -> throw IllegalArgumentException(res.message ?: "Failed to recalculate quote")
            DomainResult.Loading -> throw IllegalStateException("Unexpected loading state")
        }
    }

