    suspend fun createFinalQcInspection(
        principal: AuthenticatedPrincipal,
        executionJobId: String,
        reqDto: CreateFinalQcInspectionRequestDto
    ): FinalQcInspectionResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createFinalQcPackagingService(principal.projectId)
        val samplePlan = runCatching { InspectionSamplePlanType.valueOf(reqDto.samplePlanType) }.getOrDefault(InspectionSamplePlanType.FULL_100_PERCENT)
        val checklist = reqDto.checklist.map { QcChecklistItem(it.checkCode, it.checkTitle, it.isPassed, it.measuredValue, it.toleranceLimit, it.remarks) }

        return service.createFinalQcInspection(
            tenantId = principal.projectId,
