    suspend fun calculateActualJobCost(
        principal: AuthenticatedPrincipal,
        executionJobId: String,
        reqDto: CalculateActualJobCostRequestDto
    ): ProductionActualJobCostResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
        val service = repositoryFactory.createProductionJobCostingService(principal.projectId)
        val trackingService = repositoryFactory.createShopFloorTrackingService(principal.projectId)
        val qcService = repositoryFactory.createFinalQcPackagingService(principal.projectId)

        val materials = trackingService.listMaterialConsumptionsByJob(principal.projectId, executionJobId)
        val timeRecords = trackingService.listOperatorTimeRecordsByJob(principal.projectId, executionJobId)
        val telemetries = trackingService.listMachineTelemetryByJob(principal.projectId, executionJobId)

        val defects = qcService.listDefectsByJob(principal.projectId, executionJobId)
        val packagings = qcService.listPackagingRecordsByJob(principal.projectId, executionJobId)

        return service.calculateActualJobCost(
            tenantId = principal.projectId,
            executionJobId = executionJobId,
            orderId = reqDto.orderId,
            manufacturedGoodQuantity = reqDto.manufacturedGoodQuantity,
            materialConsumptions = materials,
            operatorTimeRecords = timeRecords,
            machineTelemetryLogs = telemetries,
            defectRecords = defects,
            packagingRecords = packagings,
            packagingUnitRate = reqDto.packagingUnitRate,
            overheadAllocationRate = reqDto.overheadAllocationRate,
            actor = principal.username
        ).toDto()
    }

