    // =========================================================================
    // MODULE 17 STEP 10: PRODUCTION JOB CLOSURE, ARCHIVAL & ENTERPRISE GOVERNANCE
    // =========================================================================

    suspend fun auditJobClosureReadiness(
        principal: AuthenticatedPrincipal,
        executionJobId: String,
        orderId: String
    ): JobClosureReadinessAuditDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val service = repositoryFactory.createProductionJobClosureService(principal.projectId)
        val execService = repositoryFactory.createProductionExecutionService(principal.projectId)
        val schedulingService = repositoryFactory.createProductionSchedulingService(principal.projectId)
        val trackingService = repositoryFactory.createShopFloorTrackingService(principal.projectId)
        val qcService = repositoryFactory.createFinalQcPackagingService(principal.projectId)
        val costingService = repositoryFactory.createProductionJobCostingService(principal.projectId)

        val jobRes = execService.getJobExecution(principal.projectId, executionJobId)
        val job: ProductionJobExecution? = if (jobRes is com.sucharu.sucharupro.domain.model.common.DomainResult.Success) jobRes.data else null
        val workOrders: List<ProductionWorkOrder> = job?.workOrders ?: emptyList()
        val schedule = schedulingService.listSchedulesForJob(principal.projectId, executionJobId).firstOrNull()
        val materials = trackingService.listMaterialConsumptionsByJob(principal.projectId, executionJobId)
        val timeRecords = trackingService.listOperatorTimeRecordsByJob(principal.projectId, executionJobId)
        val qcInspection = qcService.listInspectionsByJob(principal.projectId, executionJobId).firstOrNull()
        val release = qcService.listReleaseRecordsByJob(principal.projectId, executionJobId).firstOrNull()
        val costRecord = costingService.getActualJobCostByJob(principal.projectId, executionJobId)
        val reconResult = try {
            costingService.reconcileJobCosting(principal.projectId, executionJobId, principal.username)
        } catch (_: Exception) { null }

        return service.auditJobClosureReadiness(
            tenantId = principal.projectId,
            executionJobId = executionJobId,
            orderId = orderId,
            jobExecution = job,
            workOrders = workOrders,
            schedule = schedule,
            materialConsumptions = materials,
            timeRecords = timeRecords,
            finalQcInspection = qcInspection,
            goodsRelease = release,
            costRecord = costRecord,
            reconciliationResult = reconResult,
            actor = principal.username
        ).toDto()
    }

    suspend fun closeAndSealJob(
        principal: AuthenticatedPrincipal,
        executionJobId: String,
        reqDto: CloseAndSealJobRequestDto
    ): ProductionJobClosureResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
