            totalCostVariance = reqDto.totalCostVariance,
            reworkOrScrapUnits = reqDto.reworkOrScrapUnits,
            machineEfficiency = reqDto.machineEfficiency,
            onTime = reqDto.onTime,
            workOrderIds = workOrders.map { it.workOrderId },
            qcInspectionId = qcInspection?.inspectionId,
            packagingId = packaging?.packagingId,
            releaseId = release?.releaseId,
            costRecordId = costRecord?.costRecordId,
            primaryDowntimeDrivers = reqDto.primaryDowntimeDrivers,
            scrapAndDefectTakeaways = reqDto.scrapAndDefectTakeaways,
            costVarianceTakeaways = reqDto.costVarianceTakeaways,
            operationalRecommendations = reqDto.operationalRecommendations,
            actor = principal.username
        ).toDto()
    }



