        val materialSpec = PaperMaterialSpecification(
            materialCode = reqDto.materialCode,
            materialName = reqDto.materialName,
            stockType = PaperStockType.valueOf(reqDto.stockType),
            gsm = reqDto.gsm,
            sheetDimension = PrintingDimension(
                width = reqDto.sheetWidthMm,
                height = reqDto.sheetHeightMm,
                unit = MeasurementUnit.MILLIMETERS
            )
