        return service.resolveRequirementAndCheckAvailability(
            tenantId = principal.projectId,
            orderId = reqDto.orderId,
            orderItemId = reqDto.orderItemId,
            calculationId = reqDto.calculationId,
            materialSpec = materialSpec,
            productiveSheetsRequired = reqDto.productiveSheetsRequired,
            wasteSheetsRequired = reqDto.wasteSheetsRequired,
            availableInventoryProducts = dummyProducts,
            onHandPhysicalSheets = 50000L,
            warehouseId = reqDto.warehouseId,
            warehouseName = reqDto.warehouseName
        ).toDto()
    }

