                unit = MeasurementUnit.MILLIMETERS
            ),
            productiveSheetsRequired = reqDto.totalSheetsRequired,
            wasteSheetsRequired = 0L,
            totalSheetsRequired = reqDto.totalSheetsRequired,
            totalReamsRequired = SubstrateReservationMathUtils.calculateReams(reqDto.totalSheetsRequired),
            totalWeightKg = SubstrateReservationMathUtils.calculateTotalWeightKg(
                sheets = reqDto.totalSheetsRequired,
                gsm = reqDto.gsm,
                dimension = PrintingDimension(reqDto.sheetWidthMm, reqDto.sheetHeightMm, MeasurementUnit.MILLIMETERS)
            )
        )

        return service.createHardReservation(
            tenantId = principal.projectId,
            orderId = reqDto.orderId,
            orderItemId = reqDto.orderItemId,
            executionJobId = reqDto.executionJobId,
            workOrderId = reqDto.workOrderId,
            productId = reqDto.productId,
            sku = reqDto.sku,
            productName = reqDto.productName,
            warehouseId = reqDto.warehouseId,
            locationId = reqDto.locationId,
            batchNumber = reqDto.batchNumber,
            requirement = requirement,
            notes = reqDto.notes,
            actor = principal.username
        ).toDto()
    }

