    suspend fun getRealTimeSubstrateAvailability(
        principal: AuthenticatedPrincipal,
        sku: String,
        warehouseId: String? = null
    ): SubstrateRealTimeAvailabilityResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val service = repositoryFactory.createSubstrateReservationService(principal.projectId)
        val activeHolds = service.listAllReservations(principal.projectId)
            .filter { it.sku.equals(sku, ignoreCase = true) && it.status.isActiveHold }

        val totalReserved = activeHolds.sumOf { it.reservedSheets }
        val onHandPhysical = 50000L // Authoritative balance from Module 06 stock master
        val available = SubstrateReservationMathUtils.calculateAvailableStock(onHandPhysical, totalReserved)

        return SubstrateRealTimeAvailabilityResponseDto(
            tenantId = principal.projectId,
            sku = sku,
            warehouseId = warehouseId,
            onHandPhysicalSheets = onHandPhysical,
            currentlyReservedSheets = totalReserved,
            availableReservableSheets = available,
            totalActiveHoldCount = activeHolds.size
        )
    }

