    // --- Module 19 Step 03: Batch/Lot Selection, Grain Direction & Sheet Dimension Matching ---

    suspend fun evaluateBatchLotSelection(
        principal: AuthenticatedPrincipal,
        request: com.sucharu.sucharupro.data.api.model.substratereservation.EvaluateBatchSelectionRequestDto
    ): com.sucharu.sucharupro.data.api.model.substratereservation.BatchLotSelectionResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val service = repositoryFactory.createSubstrateBatchSelectionService(principal.projectId)

        val stockType = try {
            com.sucharu.sucharupro.domain.model.printingcalculator.PaperStockType.valueOf(request.stockType)
        } catch (_: Exception) {
            com.sucharu.sucharupro.domain.model.printingcalculator.PaperStockType.ART_PAPER
        }

        val policy = try {
            com.sucharu.sucharupro.domain.model.substratereservation.BatchSelectionPolicy.valueOf(request.selectionPolicy)
        } catch (_: Exception) {
            com.sucharu.sucharupro.domain.model.substratereservation.BatchSelectionPolicy.FIFO
        }

        val grain = com.sucharu.sucharupro.domain.model.substratereservation.PaperGrainDirection.fromString(request.requiredGrainDirection)

        val spec = com.sucharu.sucharupro.domain.model.substratereservation.BatchLotSelectionSpecification(
            selectionId = "SBS-${java.util.UUID.randomUUID().toString().take(8).uppercase()}",
            tenantId = principal.projectId,
            orderId = request.orderId,
            orderItemId = request.orderItemId,
            executionJobId = request.executionJobId,
            workOrderId = request.workOrderId,
            reservationId = request.reservationId,
            productId = request.productId,
            sku = request.sku,
            requestedMaterialName = request.requestedMaterialName,
            stockType = stockType,
            targetGsm = request.targetGsm,
            requiredSheetDimension = com.sucharu.sucharupro.domain.model.printingcalculator.PrintingDimension(
                width = request.sheetWidthMm,
                height = request.sheetHeightMm,
                unit = com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.MILLIMETERS
            ),
            requiredGrainDirection = grain,
            requiredSheets = request.requiredSheets,
            allowSheetRotation = request.allowSheetRotation,
            allowMultiBatchFulfillment = request.allowMultiBatchFulfillment,
            selectionPolicy = policy,
            preferredWarehouseId = request.preferredWarehouseId,
            actor = principal.userId
        )

        val candidateModels = request.candidateBatches.map {
            val candStockType = try {
                com.sucharu.sucharupro.domain.model.printingcalculator.PaperStockType.valueOf(it.stockType)
            } catch (_: Exception) {
                com.sucharu.sucharupro.domain.model.printingcalculator.PaperStockType.ART_PAPER
            }
            com.sucharu.sucharupro.domain.model.substratereservation.BatchLotInventoryCandidate(
                candidateId = it.candidateId,
                tenantId = principal.projectId,
                warehouseId = it.warehouseId,
                warehouseName = it.warehouseName,
                locationId = it.locationId,
                locationCode = it.locationCode,
                productId = it.productId,
                sku = it.sku,
                productName = it.productName,
                batchNumber = it.batchNumber,
                lotNumber = it.lotNumber,
                supplierLotReference = it.supplierLotReference,
                stockType = candStockType,
                gsm = it.gsm,
                sheetDimension = com.sucharu.sucharupro.domain.model.printingcalculator.PrintingDimension(
                    width = it.sheetWidthMm,
                    height = it.sheetHeightMm,
                    unit = com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.MILLIMETERS
                ),
                grainDirection = com.sucharu.sucharupro.domain.model.substratereservation.PaperGrainDirection.fromString(it.grainDirection),
                onHandPhysicalSheets = it.onHandPhysicalSheets,
                reservedSheets = it.reservedSheets,
                hardAllocatedSheets = it.hardAllocatedSheets,
                usableSheets = it.usableSheets,
                receivedTimestamp = it.receivedTimestamp,
                expiryTimestamp = it.expiryTimestamp,
                qualityRating = it.qualityRating,
                status = it.status
            )
        }

        val result = service.evaluateAndSelectBatches(spec, candidateModels)
        return result.toDto()
    }

