    // ========================================================================
    // SECTION 75: DYNAMIC IMPOSITION & SHEET LAYOUT (Module 18 Step 01)
    // ========================================================================

    suspend fun calculateImpositionLayout(
        principal: AuthenticatedPrincipal,
        request: com.sucharu.sucharupro.data.api.model.imposition.CalculateImpositionRequestDto
    ): com.sucharu.sucharupro.data.api.model.imposition.ImpositionSpecificationResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val service = repositoryFactory.createImpositionService(principal.projectId)

        val itemUnit = try {
            com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.valueOf(request.finishedItemUnit)
        } catch (e: Exception) {
            com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.MILLIMETERS
        }

        val sheetUnit = try {
            com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.valueOf(request.parentSheetUnit)
        } catch (e: Exception) {
            com.sucharu.sucharupro.domain.model.printingcalculator.MeasurementUnit.MILLIMETERS
        }

        val orientationPolicy = try {
            com.sucharu.sucharupro.domain.model.imposition.ImpositionOrientationPolicy.valueOf(request.orientationPolicy)
        } catch (e: Exception) {
            com.sucharu.sucharupro.domain.model.imposition.ImpositionOrientationPolicy.AUTO_OPTIMAL
        }

        val itemDim = com.sucharu.sucharupro.domain.model.printingcalculator.PrintingDimension(
            width = request.finishedItemWidth,
            height = request.finishedItemHeight,
            unit = itemUnit
        )

        val sheetDim = com.sucharu.sucharupro.domain.model.printingcalculator.PrintingDimension(
            width = request.parentSheetWidth,
            height = request.parentSheetHeight,
            unit = sheetUnit
        )

        val margins = com.sucharu.sucharupro.domain.model.imposition.ImpositionMarginSpec(
            topMm = request.marginTopMm,
            bottomMm = request.marginBottomMm,
            leftMm = request.marginLeftMm,
            rightMm = request.marginRightMm
        )

        val spacing = com.sucharu.sucharupro.domain.model.imposition.ImpositionSpacingSpec(
            bleedMm = request.bleedMm,
            horizontalGutterMm = request.horizontalGutterMm,
            verticalGutterMm = request.verticalGutterMm
        )

        val spec = if (request.saveSpecification) {
            service.calculateAndSave(
                tenantId = principal.projectId,
                jobId = request.jobId,
                orderId = request.orderId,
                orderItemId = request.orderItemId,
                calculationId = request.calculationId,
                productName = request.productName,
                finishedItemDimension = itemDim,
                parentSheetDimension = sheetDim,
                margins = margins,
                spacing = spacing,
                orientationPolicy = orientationPolicy,
                requiredQuantity = request.requiredQuantity,
                notes = request.notes,
                actor = principal.userId
            )
        } else {
            service.calculateOptimalLayout(
                tenantId = principal.projectId,
                jobId = request.jobId,
                orderId = request.orderId,
                orderItemId = request.orderItemId,
                calculationId = request.calculationId,
                productName = request.productName,
                finishedItemDimension = itemDim,
                parentSheetDimension = sheetDim,
                margins = margins,
                spacing = spacing,
                orientationPolicy = orientationPolicy,
                requiredQuantity = request.requiredQuantity,
                notes = request.notes,
                actor = principal.userId
            )
        }

        return spec.toDto()
    }

