            orderId = request.orderId,
            orderItemId = request.orderItemId,
            productName = request.productName,
            totalPages = request.totalPages,
            signaturePageCount = request.signaturePageCount,
            bindingMethod = com.sucharu.sucharupro.domain.model.imposition.BindingMethod.valueOf(request.bindingMethod),
            sheetTurningMethod = com.sucharu.sucharupro.domain.model.imposition.SheetTurningMethod.valueOf(request.sheetTurningMethod),
            foldingScheme = com.sucharu.sucharupro.domain.model.imposition.FoldingScheme.valueOf(request.foldingScheme),
