    suspend fun generateCtpFromSignature(
        principal: AuthenticatedPrincipal,
        request: com.sucharu.sucharupro.data.api.model.imposition.GenerateCtpFromSignatureRequestDto
    ): com.sucharu.sucharupro.data.api.model.imposition.CtpOutputSpecificationResponseDto {
        BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF, UserRole.AI_AGENT)
        val service = repositoryFactory.createCtpOutputService(principal.projectId)

        val plateSpec = if (request.plateWidthMm != null && request.plateHeightMm != null) {
            com.sucharu.sucharupro.domain.model.imposition.PlateDimensionSpec(
                plateWidthMm = request.plateWidthMm,
                plateHeightMm = request.plateHeightMm,
                plateThicknessMm = request.plateThicknessMm,
                gripperMarginMm = request.gripperMarginMm,
                tailMarginMm = request.tailMarginMm,
                sideGuideMarginLeftMm = request.sideGuideMarginLeftMm,
                sideGuideMarginRightMm = request.sideGuideMarginRightMm
            )
        } else null

        val resolution = when (request.resolutionDpi) {
            1200 -> com.sucharu.sucharupro.domain.model.imposition.OutputResolutionDpi.DPI_1200
            2400 -> com.sucharu.sucharupro.domain.model.imposition.OutputResolutionDpi.DPI_2400
            4000 -> com.sucharu.sucharupro.domain.model.imposition.OutputResolutionDpi.DPI_4000
            else -> com.sucharu.sucharupro.domain.model.imposition.OutputResolutionDpi.DPI_2540
        }

        val markPolicy = com.sucharu.sucharupro.domain.model.imposition.PrepressMarkPolicy(
            includeRegistrationMarks = request.includeRegistrationMarks,
            includeCropMarks = request.includeCropMarks,
            includeBleedMarks = request.includeBleedMarks,
            includeColorBars = request.includeColorBars,
            includePlateSlugs = request.includePlateSlugs
        )

        val colorSeps = request.colorSeparations.map {
            com.sucharu.sucharupro.domain.model.imposition.PlateColorSeparation.valueOf(it.uppercase())
        }

        val spec = service.generateFromSignature(
            tenantId = principal.projectId,
            signatureImpositionId = request.signatureImpositionId,
            plateDimensionSpec = plateSpec,
            resolutionDpi = resolution,
            screeningMethod = com.sucharu.sucharupro.domain.model.imposition.ScreeningMethod.valueOf(request.screeningMethod.uppercase()),
            screenRulingLpi = request.screenRulingLpi,
            markPolicy = markPolicy,
            colorSeparations = colorSeps,
            spotColorNames = request.spotColorNames,
            actor = principal.userId
        )

        return spec.toDto()
    }

